package com.example.starter.domain;

/**
 * 粮仓流转状态。
 */
public enum SiloStatus {
    /** 日常监测 */
    MONITORING,
    /** 异常告警 */
    ALARM,
    /** 通风作业执行中 */
    VENTILATING,
    /** 通风完成待复测 */
    RETEST_PENDING,
    /** 复测超标（一轮后可二次通风） */
    RETEST_FAIL,
    /** 复测达标 */
    RETEST_PASS,
    /** 两轮复测仍超标，转人工处置 */
    MANUAL,
    /** 已归档（终态） */
    ARCHIVED
}

package com.example.starter.domain;

/**
 * 通风目的。
 */
public enum VentilationPurpose {
    /** 降温 */
    COOLING,
    /** 降水 */
    DEHUMIDIFY,
    /** 调质 */
    QUALITY
}

package com.example.starter.domain;

/**
 * 通风作业状态。
 */
public enum OperationStatus {
    /** 执行中 */
    EXECUTING,
    /** 已完成（风机已释放） */
    COMPLETED
}

package com.example.starter.domain;

/**
 * 幂等请求类型。
 */
public enum RequestKind {
    /** 告警 */
    ALARM,
    /** 通风令 */
    VENTILATION,
    /** 复测 */
    RETEST,
    /** 归档 */
    ARCHIVE
}

package com.example.starter.domain;

/**
 * 温湿度数据所属业务阶段。
 */
public enum ReadingPhase {
    /** 日常上报 */
    DAILY,
    /** 告警采样 */
    ALARM,
    /** 一轮复测 */
    ROUND_1,
    /** 二轮复测 */
    ROUND_2
}

