        @NotBlank String siloCode,
        @NotBlank String fanCode,
        @NotBlank String purpose,
        @NotNull @Positive Double ambientHumidity,
        @NotNull LocalDateTime startTime,
        @NotNull LocalDateTime endTime
) {
}

